  picker.fill('zzzznotaterritory');check('Empty municipality search explains no matches',page.get_by_text('No territory matches your search.',exact=True).is_visible())
  page.keyboard.press('Escape');check('Escape keeps the previously selected territory',picker.get_attribute('data-region-id')=='para')
  picker.fill('Portel');picker.press('ArrowDown');picker.press('Enter');settle(page)
  check('Keyboard search selects Portel and shares it in the URL',picker.get_attribute('data-region-id')=='portel' and 'regiao=portel' in page.url)
  page.wait_for_function(MAP);page.wait_for_function('!window.__qaMap.isMoving()')
  page.evaluate('window.__originalMap=window.__qaMap')
  handle=page.get_by_role('separator',name='Resize map and observation details',exact=True);before=page.locator('.map-stage').bounding_box()['width'];box=handle.bounding_box()
  page.mouse.move(box['x']+box['width']/2,box['y']+box['height']/2);page.mouse.down();page.mouse.move(box['x']-70,box['y']+box['height']/2,steps=10);page.mouse.up();page.wait_for_timeout(700)
  after=page.locator('.map-stage').bounding_box()['width'];check('Pointer drag resizes the map and details',abs(after-before)>30,{'before':before,'after':after})
  handle.focus();handle.press('ArrowRight');page.wait_for_timeout(300);check('Resize handle supports the keyboard',abs(page.locator('.map-stage').bounding_box()['width']-after)>1)
  check('Resize retains MapLibre and updates canvas dimensions',page.evaluate('window.__originalMap===window.__qaMap && Math.abs(window.__qaMap.getCanvas().getBoundingClientRect().width-document.querySelector(".map-stage").clientWidth)<2'))
  page.get_by_role('radio',name='48 hours',exact=True).click();settle(page)
