  records=page.locator('[data-table-id=observations]');check('Observation table uses the real filtered map dataset',int(page.locator('[data-feature-count]').get_attribute('data-feature-count'))>0 and records.get_by_role('row').count()>1)
  records.get_by_role('button',name=re.compile('^FRP')).click();check('FRP column sorts with explicit MW units',records.locator('th[aria-sort]').count()==1 and 'MW' in records.locator('th[aria-sort]').inner_text())
  check('Confidence remains sensor-specific and is not ranked across sensors',records.get_by_role('columnheader',name=re.compile('^Confidence')).get_by_role('button').count()==0)
  records.get_by_role('button',name='Columns',exact=True).click();page.get_by_role('checkbox',name='Coordinates',exact=True).uncheck();page.keyboard.press('Escape')
  check('Column picker hides the chosen column',records.get_by_role('columnheader',name='Coordinates',exact=True).count()==0)
  with page.expect_download() as dl:page.get_by_role('link',name='Export CSV',exact=True).click()
  path=OUT/'observations-original.csv';dl.value.save_as(path);header=path.read_text().splitlines()[0]
  check('Column choices preserve full original CSV fields','latitude' in header and 'longitude' in header and 'frp' in header.lower())
  page.reload(wait_until='networkidle');settle(page);records=page.locator('[data-table-id=observations]')
  check('Column preference and observation period survive reload',records.get_by_role('columnheader',name='Coordinates',exact=True).count()==0 and page.get_by_role('radio',name='48 hours',exact=True).get_attribute('aria-checked')=='true')
  if records.get_by_role('button',name='Next page',exact=True).is_enabled():records.get_by_role('button',name='Next page',exact=True).click()
  records.get_by_role('textbox',name='Search table',exact=True).fill('zzzz-no-record')
  check('Table search gives an explicit empty state',records.get_by_text('No records match your search.',exact=True).is_visible())
  records.get_by_role('textbox',name='Search table',exact=True).fill('NOAA21');check('Search resets pagination to available records','Page 1 of' in records.locator('.data-pagination').inner_text())
  records.get_by_role('textbox',name='Search table',exact=True).fill('');snap(page,'after-desktop-observation-table');axe(page,'desktop-observations')
  records.locator('.table-observation-link').first.click();page.get_by_role('heading',name='Thermal detection',exact=True).wait_for();page.wait_for_timeout(600)
  check('Clicking a table record opens its real satellite details',page.get_by_role('complementary',name='Observation details').get_by_text('Coordinates',exact=True).count()==1)
  page.get_by_label('Close detection detail').click();page.evaluate('scrollTo(0,0)');snap(page,'after-desktop-map')
  page.get_by_role('link',name='Evidence & exports',exact=True).click();settle(page)
  files=page.locator('[data-table-id=historical-sources]');files.get_by_role('textbox',name='Search table',exact=True).fill('VIIRS_SNPP_SP')
  check('Historical provenance table filters by original sensor ID',files.get_by_role('row').count()==3)
  files.get_by_role('button',name='Columns',exact=True).click();page.get_by_role('checkbox',name='SHA-256',exact=True).check();page.keyboard.press('Escape');check('Source hash can be shown beside the scientific record',files.get_by_role('columnheader',name='SHA-256',exact=True).count()==1)
  page.evaluate('scrollTo(0,0)');snap(page,'after-desktop-evidence');axe(page,'desktop-evidence')
  page.get_by_role('link',name='Fire history',exact=True).click();page.get_by_role('tab',name='Observed records',exact=True).click();settle(page)
  rangeform=page.locator('.date-range-control').first
  original=rangeform.locator('.date-range-applied').inner_text();rangeform.get_by_label('Period A: start').fill('2025-01-01');rangeform.get_by_label('Period A: end').fill('2024-01-01')
  check('Invalid date order is explained and cannot be applied',rangeform.get_by_role('button',name='Apply Period A',exact=True).is_disabled() and 'on or after' in rangeform.locator('.date-range-error').inner_text())
  check('Editing invalid dates preserves the applied comparison',rangeform.locator('.date-range-applied').inner_text()==original)
  rangeform.get_by_label('Period A: start').fill('2024-02-29');rangeform.get_by_label('Period A: end').fill('2024-02-29');rangeform.get_by_role('button',name='Apply Period A',exact=True).click();settle(page)
  check('A valid single UTC day can be explicitly applied','29 Feb 2024' in rangeform.locator('.date-range-applied').inner_text());rangeform.scroll_into_view_if_needed();snap(page,'after-desktop-periods');axe(page,'desktop-history')
  mobile=browser.new_context(viewport={'width':390,'height':844});mobile.add_init_script("localStorage.setItem('amazonia-viva:language','pt-BR')");mp=mobile.new_page();mp.set_default_timeout(60000);mp.on('pageerror',lambda e:errors.append(str(e)));mp.on('console',lambda m:console.append(m.text) if m.type=='error' else None)
  mp.goto(args.base+'/?regiao=para',wait_until='networkidle');settle(mp);mp.get_by_role('combobox',name='Território selecionado',exact=True).fill('Portel');mp.locator('[role=option][data-region-id=portel]').click();settle(mp)
  check('Mobile search shares the selected municipality',mp.get_by_label('Território selecionado').get_attribute('data-region-id')=='portel' and fits(mp));snap(mp,'after-mobile-map')
  mp.locator('.recent-observations button').first.click();dialog=mp.get_by_role('dialog',name='Detalhes da observação',exact=True);dialog.wait_for()
  dialog.get_by_text('Coordenadas',exact=True).wait_for();check('Mobile detection opens an accessible sheet with scientific metadata',dialog.get_by_text('FRP',exact=True).count()==1 and dialog.get_by_text('Sensor',exact=True).count()==1 and dialog.get_by_label('Fechar detalhe da detecção').count()==1)
  check('Mobile sheet fits the viewport',mp.evaluate("(()=>{const r=document.querySelector('[role=dialog]').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight+1})()"));snap(mp,'after-mobile-observation-sheet');axe(mp,'mobile-sheet')
  mp.keyboard.press('Escape');check('Escape dismisses the mobile sheet and keeps the territory',mp.get_by_role('dialog').count()==0 and mp.get_by_label('Território selecionado').get_attribute('data-region-id')=='portel')
  mt=mp.locator('[data-table-id=observations]');mt.get_by_role('button',name='Colunas',exact=True).click();check('Mobile column controls fit on screen',mp.evaluate("(()=>{const r=document.querySelector('[data-slot=popover-content]').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1})()"));snap(mp,'after-mobile-columns');mp.keyboard.press('Escape');check('Mobile observation table scrolls inside its own region',fits(mp));axe(mp,'mobile-observations')
  mp.get_by_role('link',name='Histórico do fogo',exact=True).click();mp.get_by_role('tab',name='Registros observados',exact=True).click();settle(mp);check('Portuguese history and period controls fit mobile',fits(mp));axe(mp,'mobile-history')
  mp.goto(args.base+'/evidencias?regiao=portel',wait_until='networkidle');settle(mp);check('Portuguese evidence tables fit mobile',fits(mp));snap(mp,'after-mobile-evidence');axe(mp,'mobile-evidence');mobile.close()
  check('No runtime or unexpected network errors',not errors and not console and not http,{'errors':errors,'console':console,'http':http})
